{
  "name": "Keithley 580 微欧计",
  "name_en": "Keithley 580 Micro-ohmmeter",
  "manufacturer": "Keithley Instruments",
  "description": "Keithley 580 是一台4位半分辨率的自动量程微欧计，用于测量约 10 µΩ 到 200 kΩ 的低电阻。它适合实验室和电子测试中的精密低阻测量，如接触电阻、导线、电阻元件及其他低阻样品的表征，并支持相对测量、干电路测试以及触发测量操作。",
  "description_en": "The Keithley 580 is a 4.5-digit autoranging micro-ohmmeter for measuring low resistance from about 10 µΩ to 200 kΩ. It is used in laboratories and electronics testing for precise low-resistance characterization of contacts, wires, resistive components, and other low-ohmic samples, with support for relative measurements, dry-circuit testing, and triggered operation.",
  "tag_hints": [
    "micro-ohmmeter",
    "low resistance measurement",
    "autoranging resistance meter",
    "contact resistance testing",
    "dry circuit test",
    "pulsed or DC drive"
  ],
  "actions": [
    {
      "action_name": "auto-auto_range",
      "description": "启用自动量程。",
      "description_en": "Enable auto range."
    },
    {
      "action_name": "auto-drive",
      "description": "获取/设置测量驱动方式（脉冲或直流）。",
      "description_en": "Get/set the measurement drive mode (pulsed or DC)."
    },
    {
      "action_name": "auto-dry_circuit_test",
      "description": "获取/设置干电路测试模式。",
      "description_en": "Get/set the dry-circuit test mode."
    },
    {
      "action_name": "auto-input_range",
      "description": "获取/设置电阻输入量程。",
      "description_en": "Get/set the resistance input range."
    },
    {
      "action_name": "auto-measure",
      "description": "执行一次电阻测量。",
      "description_en": "Perform a resistance measurement."
    },
    {
      "action_name": "auto-operate",
      "description": "获取/设置工作状态（操作/待机）。",
      "description_en": "Get/set the operating state (operate/standby)."
    },
    {
      "action_name": "auto-parse_status_word",
      "description": "解析设备返回的状态字。",
      "description_en": "Parse the status word returned by the instrument."
    },
    {
      "action_name": "auto-polarity",
      "description": "获取/设置测量极性。",
      "description_en": "Get/set the measurement polarity."
    },
    {
      "action_name": "auto-query",
      "description": "发送查询命令并读取设备响应。",
      "description_en": "Send a query command and read the instrument response."
    },
    {
      "action_name": "auto-relative",
      "description": "获取/设置相对测量模式。",
      "description_en": "Get/set the relative measurement mode."
    },
    {
      "action_name": "auto-sendcmd",
      "description": "向设备发送命令字符串。",
      "description_en": "Send a command string to the instrument."
    },
    {
      "action_name": "auto-set_calibration_value",
      "description": "设置校准值。",
      "description_en": "Set the calibration value."
    },
    {
      "action_name": "auto-store_calibration_constants",
      "description": "存储校准常数。",
      "description_en": "Store the calibration constants."
    },
    {
      "action_name": "auto-trigger",
      "description": "触发设备执行已接收的命令。",
      "description_en": "Trigger the instrument to execute received commands."
    },
    {
      "action_name": "auto-trigger_mode",
      "description": "获取/设置触发模式。",
      "description_en": "Get/set the trigger mode."
    },
    {
      "action_name": "auto-get_status_word",
      "description": "获取状态字。",
      "description_en": "Get the status word."
    },
    {
      "action_name": "auto-parse_measurement",
      "description": "解析设备返回的测量结果字符串。",
      "description_en": "Parse the measurement string returned by the instrument."
    }
  ]
}

